namespace MaintenancePRO.ViewModels; public sealed class BreakdownViewModel:BaseViewModel { public string EquipmentCode{get;set;}=""; public string Severity{get;set;}="Moyenne"; public string Description{get;set;}=""; public Command SaveCommand=>new(async()=>{if(string.IsNullOrWhiteSpace(EquipmentCode)||string.IsNullOrWhiteSpace(Description)||Description.Length>1000){await Shell.Current.DisplayAlert("Vérification","Renseigne l’équipement et une description de 1 à 1000 caractères.","OK");return;} await Shell.Current.DisplayAlert("Démo","Déclaration validée localement. Aucun envoi serveur n’a été effectué.","OK");}); }